export const $PaymentStatus = {
    type: 'string',
    description: `Where your payment is in its lifecycle. One payment reads the same however you ask
about it.

- \`pending\`: accepted and in progress. Nothing has reached the recipient yet.
- \`finalizing\`: the transaction paying your recipient is on chain, but its chain has
  not yet judged it final. NOT FINAL, see below.
- \`completed\`: delivered and final on the destination chain.
- \`failed\`: did not complete. Any funds held in escrow are returned, and \`error\`
  describes what went wrong.
- \`refunding\`: the settler will not deliver this payment and your funds are being
  returned from escrow. NOT FINAL: it becomes \`refund_available\` or \`refunded\`, and it
  can still become \`completed\` or \`failed\`.
- \`refund_available\`: the settler did not deliver and the refund is authorized for you
  to submit. GET /v1/payments/{paymentId}/status returns \`refund_signature\`, which you
  submit to the source escrow to return your funds. The other responses report this
  status without the signature. NOT FINAL: the funds are still in escrow, so it becomes
  \`refunded\` once the refund lands, or \`completed\` if the settler delivers late and is
  paid first. Do not pay again while it is \`refund_available\`.
- \`refunded\`: your funds were returned from the source escrow. \`transactions.refund\` is
  the refund transaction, when it is known. On Solana, GET /v1/payments/{paymentId}/status
  may also return \`refunded_amount\`, how much came back, and \`refund_partial\`, whether
  that was less than the deposit. The other responses report this status without them.

\`completed\`, \`failed\` and \`refunded\` are final and will not change afterwards.
\`pending\`, \`finalizing\`, \`refunding\` and \`refund_available\` will.

**Do not treat \`finalizing\` as delivered.** It says the payment has been made on
chain but is not yet irreversible, much as a card authorization is not yet a
settlement. It normally becomes \`completed\`, after seconds on some chains and minutes
on others. If a chain reorganization drops the transaction before it is final, your
funds are refunded instead. Acting on
\`finalizing\` — releasing goods, crediting an account — means accepting that risk
deliberately, at whatever threshold suits you rather than the one we wait for.

\`finalizing\` is about paying the recipient. While your own funds are still being
committed on the source chain the payment is \`pending\`, because nothing has reached
the recipient yet.
`,
    enum: ['pending', 'finalizing', 'completed', 'failed', 'refunding', 'refund_available', 'refunded'],
    example: 'pending'
} as const;

export const $PaymentTransaction = {
    type: 'object',
    description: `One on-chain transaction belonging to a payment: which chain, which transaction, and
which block it landed in.

Whether the payment has actually happened is answered by \`status\`, not here. Read this
to look the transaction up on chain and to verify it yourself.
`,
    required: ['transaction_hash', 'chain_id'],
    properties: {
        transaction_hash: {
            type: 'string',
            description: `The transaction's hash on its chain. Hex hashes carry the \`0x\` prefix, including on
Tron, whose own tooling omits it.
`,
            pattern: '^(0x[a-fA-F0-9]{64}|[1-9A-HJ-NP-Za-km-z]{32,88})$',
            example: '0x1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef'
        },
        chain_id: {
            type: 'string',
            description: 'CAIP-2 identifier of the chain the transaction is on.',
            pattern: '^[a-z0-9]+:[a-zA-Z0-9_-]+$',
            example: 'eip155:42161'
        },
        block_number: {
            type: 'integer',
            description: `The block the transaction landed in. Absent until it has been mined.

Provisional while \`status\` is \`finalizing\`: a reorganization can still move the
transaction to a different block. Settled once \`status\` is \`completed\` — keep it as
a final record only from then.
`,
            example: 61234567
        }
    }
} as const;

export const $PaymentTransactions = {
    type: 'object',
    description: `The transactions a payment has produced, one entry per stage, added as each becomes
known. A stage absent here has produced no transaction yet.

These are the movements that decide whether your payment happened: your funds being
committed, your recipient being paid, and your funds being returned when the payment
is refunded. Present on every outcome, so a payment that did not complete can still be
traced on chain.

Where a stage is attempted more than once, the entry describes the attempt that
counts — the one that succeeded, or the last one if none did.
`,
    properties: {
        deposit: {
            allOf: [
                {
                    '$ref': '#/components/schemas/PaymentTransaction'
                }
            ],
            description: 'Committing your funds on the source chain.'
        },
        fulfillment: {
            allOf: [
                {
                    '$ref': '#/components/schemas/PaymentTransaction'
                }
            ],
            description: 'Paying your recipient on the destination chain.'
        },
        refund: {
            allOf: [
                {
                    '$ref': '#/components/schemas/PaymentTransaction'
                }
            ],
            description: `Returning your funds from the escrow on the source chain. Can be absent on a
\`refunded\` payment when the refund transaction is not known.
`
        }
    }
} as const;

export const $RefundSignature = {
    type: 'object',
    description: `The refund authorization for a \`refund_available\` payment, as the verifier signed it.
Submit it to the source chain's escrow \`refund\` to return your funds yourself.

Anyone holding it can submit the refund, but the escrow only ever pays the depositor. If
the settler delivers late and is paid first, the refund no longer goes through.
On Solana the submitter also receives the rent of the deposit account the refund closes.
`,
    required: ['signature', 'message_hash', 'message_prehash'],
    properties: {
        signature: {
            type: 'string',
            description: `The verifier's signature over \`message_hash\`. Hex with the \`0x\` prefix on EVM and
Tron chains, hex without it on Solana.
`
        },
        message_hash: {
            type: 'string',
            description: 'The signed digest, hex without the `0x` prefix.'
        },
        message_prehash: {
            type: 'string',
            description: `The signed message as JSON. On EVM and Tron chains it carries the RefundWitness the
escrow's \`refund\` takes.
`
        }
    }
} as const;

export const $PaymentResponse = {
    type: 'object',
    description: `Response from submitting a payment request. If settlement completes inside the
gateway's synchronous window, the response is \`completed\` and \`transactions\` carries
both the deposit and the payout. The window also ends when the payment reaches \`finalizing\`,
so the response normally carries the payout transaction (\`transactions.fulfillment\`)
within seconds. Otherwise you receive a payment_id plus the payment's current
\`status\`, and can poll /v1/payments/{paymentId}/status for updates.

Read \`status\` before deciding what to do next: a \`pending\` or \`finalizing\` payment is
in flight and must NOT be re-submitted under a new request_id (that would be a second
payment), whereas a \`failed\` one is terminal — re-submitting it under the SAME
request_id resolves to the same terminal payment, so a genuine re-attempt needs a
new request_id.

**A synchronously-completed payment carries proof of QUOTE as well as of delivery.** When
settlement lands inside the window you get \`status: completed\`, the deposit and payout in
\`transactions\`, and — since a quote necessarily was awarded to get there —
\`quote_id\` and \`fulfillment_quote\`. The fast path therefore needs no follow-up call to
verify: recompute \`quote_hash\` over the returned quote and compare it against the on-chain
commitment from this response alone.

\`status\` is present on every response. \`completed\` is always accompanied by
\`transactions.deposit\` and \`transactions.fulfillment\`: either one missing from a
\`completed\` payment is a gateway fault, to report with the \`payment_id\`. \`failed\` is
accompanied by \`error\` where a reason has been recorded.
`,
    required: ['payment_id', 'status', 'idempotent_replay'],
    properties: {
        payment_id: {
            type: 'string',
            description: `Unique ID for tracking this payment. Save this to check status later.
`,
            example: '0x761989729fefb4b0cb8b3e6f787301a3878c91e8fba35ed362a079292879f34f'
        },
        status: {
            '$ref': '#/components/schemas/PaymentStatus'
        },
        transactions: {
            '$ref': '#/components/schemas/PaymentTransactions'
        },
        idempotent_replay: {
            type: 'boolean',
            description: `Whether this response describes a payment that already existed, rather than one
created by this request. \`true\` means the request_id had been used before and you
are being handed the ORIGINAL payment — no second payment was created and nothing
additional was charged.

**Re-attempting a payment.** Re-submit the same request and you get the same payment
back. You may re-send the original bytes unchanged: the deadlines will have expired by
then — \`quote_deadline\` bounds the auction and is short, while this endpoint may hold a
submission for up to 30 seconds — and an expired deadline on a re-submission is not an
error, because the request is resolved onto the payment that already exists rather than
used to create one.

Re-signing with fresh deadlines is equally fine and returns the same payment. What you
must NOT change is the request_id, and what you must not change under it is the
payment's economics — source, destination, fulfillment_amount, max_source_amount — which
are rejected with 409 IDEMPOTENCY_TERMS_MISMATCH. Deadlines and the signature are
exempt precisely so that a re-attempt is possible.

A direct deposit, one you fund yourself before you submit, is the exception: re-send
the bytes you funded, because the deposit commits the request. A re-submission that
moved only its deadlines is normally still handed the payment that holds this
\`request_id\`.
Check that its \`payment_id\` is the id of the deposit you funded, from your deposit
transaction rather than from a request you built again. If it is not, take your
deposit back with \`refundUnreserved\` and start again under a new \`request_id\` and
deposit nonce.

A genuinely new payment needs a NEW request_id. In particular a \`failed\` payment is
terminal: re-submitting its request_id keeps returning that dead payment, so recovering
means starting a new one under a new key.

Present on every response, \`false\` for a newly created payment. A response without
the field is from a gateway predating it, not a newly created payment.

This is the field to read when reconciling a suspected double charge: two
submissions where the second reports \`true\` are one payment, whereas two both
reporting \`false\` are two. It says nothing about how far the payment has got —
read \`status\` for that.
`,
            example: false
        },
        quote_id: {
            type: 'string',
            description: `The winning quote's ID. Present when \`status\` is \`completed\` — a payment cannot settle
without an award — and absent on a \`pending\` response, where no quote has been selected
yet. Same value and meaning as on GET /v1/payments/{paymentId}/status.
`,
            example: '0x9a3b...e8d4'
        },
        fulfillment_quote: {
            type: 'object',
            description: `The settler-signed FulfillmentQuote for the winning quote, returned verbatim as an
opaque signed document — the PREIMAGE of the \`quote_hash\` committed on-chain. Same
value, semantics and canonicalization caveats as on
GET /v1/payments/{paymentId}/status; see that field for how to verify it.

Present when \`status\` is \`completed\`. It may be absent even then, if the stored quote
is unreadable: the award is reported through \`quote_id\` regardless, so a present
\`quote_id\` with no \`fulfillment_quote\` means "verification preimage unavailable" and
never "no quote was awarded". A consumer that requires the preimage should fall back to
the status endpoint rather than treat the payment as unverified.
`,
            'x-go-type': 'json.RawMessage'
        },
        fulfillment_authorization: {
            type: 'object',
            description: `The settler-signed FulfillmentAuthorization for this payment, returned verbatim as an
opaque signed document (structurally the canonical FulfillmentAuthorization/v1 declaration at
https://schemas.atum.xyz/declarations/FulfillmentAuthorization/v1; see also
\`#/components/schemas/FulfillmentAuthorization\`). The inner declaration requires
\`version\`, \`scheme\`, \`authorization\` (the signed EIP-3009 transfer, in \`authorization.message_prehash\`), \`fulfillment_quote_json\`,
and \`evidence\` (the on-chain authorizeFulfillment transaction). On the wire the settler
typically wraps that declaration in JSON-LD with \`@context\`, \`type\`, and \`proof\` — those
envelope fields ride alongside the declaration and MUST be preserved byte-for-byte.

Present when the settler authorized an originator fulfill. Until the originator
fulfills, \`transactions.fulfillment\` is absent.

The service returns these bytes verbatim and does not re-serialize through a typed
representation (which would normalize timestamps and reorder JSON-LD envelope fields).
`,
            'x-go-type': 'json.RawMessage'
        },
        error: {
            '$ref': '#/components/schemas/PaymentFailure'
        },
        refund_reason: {
            allOf: [
                {
                    '$ref': '#/components/schemas/PaymentFailure'
                }
            ],
            description: `Why the settler did not deliver, as it reported when it gave up. Present only when
\`status\` is \`refunding\`, \`refund_available\` or \`refunded\`, and absent when the refund
started without a reason from the settler. \`status\` decides what to do next: its
\`retry_classification\` and \`request_id_reusable\` describe the settler's error, not
this payment, and never mean paying again while it is \`refunding\` or \`refund_available\`.
`
        },
        requested_count: {
            type: 'integer',
            description: `How many settler agents this payment's auction was broadcast to. Accompanies
\`decline_summary\` and is present under the same condition. Same meaning and same
absence rule as on GET /v1/payments/{paymentId}/status: absent means unknown, never
zero.
`,
            example: 8
        },
        decline_summary: {
            type: 'array',
            description: `Why the payment drew few or no quotes, carried on the submission response so that a
\`failed\` payment explains itself here rather than requiring a follow-up read. A
payment that ran out its quote deadline reports \`NO_QUOTES_RECEIVED\` on \`error\`;
this is what the settlers actually said.

Present when \`status\` is \`failed\`, alongside \`error\`. A submission rejected before
its auction opened is answered as an error response rather than this type and carries
no breakdown, and GET /v1/payments/{paymentId}/status reports the breakdown in every
state.

Same counting rules as GET /v1/payments/{paymentId}/status: every declining agent is
counted exactly once under its most recent reason, empty means no agent declined,
absent means the breakdown could not be read. The free-form decline detail is never
relayed.
`,
            items: {
                '$ref': '#/components/schemas/DeclineSummaryEntry'
            }
        }
    }
} as const;

