export const $ErrorResponse = {
    type: 'object',
    description: `Safe, outward-facing error. Derived from an internal error through the shared error catalog. The public code identifies the category and the message is a curated, safe description.

A panic is caught by shared middleware that responds \`{"error": "Internal server error occurred"}\` instead, so a 500 is not guaranteed to carry this shape.`,
    required: ['code', 'message'],
    properties: {
        code: {
            type: 'string',
            description: 'Public, machine-readable error category in SCREAMING_SNAKE_CASE.',
            pattern: '^[A-Z][A-Z0-9_]*$',
            example: 'INVALID_SOURCE_ASSET'
        },
        message: {
            type: 'string',
            description: 'Curated, safe, human-readable message.',
            maxLength: 500,
            example: 'The source asset identifier is not a valid CAIP-19 asset.'
        },
        request_id: {
            type: 'string',
            description: 'Correlation id to quote to support to locate the internal error record.',
            example: 'req_123456789'
        },
        payment_id: {
            type: 'string',
            description: 'The payment this error was raised against. Absent when the error is not about a specific payment.',
            example: '0xc7108e200d11580e7e75185991084b42a535af588ba8267cd0d1e7df089e5c9c'
        },
        docs_url: {
            type: 'string',
            format: 'uri',
            description: 'Link to the documentation page for this public code.'
        },
        domain: {
            type: 'string',
            description: 'Originating service domain.',
            example: 'PAYMENT_GATEWAY'
        },
        retry_classification: {
            type: 'string',
            description: `What the caller should do next. Absent means the condition has not been classified, which is not the same as safe to retry.
Re-sending the same \`request_id\` is an idempotent replay and always safe. This value is about submitting a new one, which starts a new operation. See https://docs.atum.xyz/errors for the value set.`,
            example: 'RECONCILE_THEN_DECIDE'
        },
        request_id_reusable: {
            type: 'boolean',
            description: 'Whether the caller may re-send this same request_id. True means no payment was created for it, so the id is still free. False means a payment exists for it, so the id is spent and re-sending only replays this outcome. Absent means undetermined, which a caller should read as false. Separate from retry_classification, which answers what the caller must change rather than whether the id survived.',
            example: false
        }
    }
} as const;

export const $CreateQuoteRequest = {
    type: 'object',
    description: `Request body for opening a quote-request batch. Structurally the existing PaymentRequest
with \`sender_auth\` omitted (the spend authorization is deferred to the award call); see
schemas/declarations/PaymentRequest/v1/schema.json.
`,
    required: ['version', 'request_id', 'source', 'destination', 'fulfillment_amount', 'quote_deadline', 'fulfillment_deadline', 'fulfillment_verifier', 'escrow_contract_address'],
    properties: {
        version: {
            type: 'string',
            description: `Semver-shaped declaration version (MAJOR.MINOR), locked to major 1 for v1. Producers emit
the canonical value exported by the bindings' Version constant.
`,
            pattern: '^1\\.[0-9]+$',
            example: '1.0'
        },
        request_id: {
            type: 'string',
            description: `Client-supplied idempotency key for this quote-request. The same request_id from the
same originator returns the same quote_request_id. Independent of the award-call request_id.
`,
            example: 'qr-2026-04-29-001'
        },
        source: {
            '$ref': '#/components/schemas/OwnedAsset'
        },
        destination: {
            type: 'array',
            description: `Array of destination assets for the settlement agent to choose from (at least one required, at most 16).
The ceiling bounds the fan-out one request can buy: every consumer iterates this list.
`,
            minItems: 1,
            maxItems: 16,
            items: {
                '$ref': '#/components/schemas/OwnedAsset'
            }
        },
        fulfillment_amount: {
            type: 'string',
            description: 'The exact amount to be received at the destination (smallest unit, e.g. wei or cents).',
            minLength: 1,
            pattern: '^[0-9]+$',
            example: '100000000'
        },
        max_source_amount: {
            type: 'string',
            description: `Optional cap on what the originator is willing to spend from source (smallest unit).
Quotes with source_amount above this are filtered. No cap applied if omitted; an empty
string is refused.
`,
            minLength: 1,
            pattern: '^[0-9]+$',
            example: '101000000'
        },
        quote_deadline: {
            type: 'string',
            format: 'date-time',
            description: `Required. End of the collection window. After this point no new quotes are accepted.
The gateway injects no default and never mutates the originator-supplied body, so the
value is carried through verbatim to the award call. It must be supplied and must be in
the future. Must be strictly earlier than fulfillment_deadline.

Keep this window short. A settler holds its quoted price for a limited period of its
own choosing, counted from when it receives the request, and declines a request whose
window ends after that hold with QUOTE_WINDOW_TOO_LONG. Each quote can be awarded as
soon as it is listed, so waiting for the window to close only takes time from the
award.

Do not make it too short either. A settler that has work to do before it can quote,
such as sourcing the payout asset through a swap, and cannot finish it by this deadline
declines with QUOTE_WINDOW_TOO_SHORT. Reissue with a longer quote_deadline. That work
time varies by settler, so there is no fixed minimum. A settler waiting on another
service cannot tell slow from down, so if the longer window is declined with a reason
whose retry_classification is not NOT_RETRYABLE_FIX_REQUEST, the cause is on the
settler's side, not in your request. Both bounds are counted from when a settler
receives the request.
`,
            example: '2026-04-29T12:00:03Z'
        },
        fulfillment_deadline: {
            type: 'string',
            format: 'date-time',
            description: `Required. The time by which the payout to the recipient must be mined on the
destination chain. If no payout is mined by then, your escrowed funds are refunded.
The payout does not have to be final by then: \`completed\`
follows once the destination chain judges it final. The gateway injects no default and
never mutates the originator-supplied body, so the value is carried through verbatim to
the award call. It must be supplied and must be in the future. Must be strictly later
than quote_deadline.
`,
            example: '2026-04-29T12:30:00Z'
        },
        settler_auth_required: {
            type: 'object',
            description: 'Policy requirements for settler authentication. Keys are policy names, values indicate if required.',
            additionalProperties: {
                type: 'boolean'
            }
        },
        originator_auth: {
            '$ref': '#/components/schemas/VerifiableCredentialAuth'
        },
        quote_selector: {
            type: 'string',
            description: `The account that picks the settler at award: the award's \`sender_auth\` names it as
the \`reserver\`, and it signs the award's \`reserve_auth\`. Name it on every quote
request: \`source.account\` to have its owner pick, the usual case. A payment service
provider paying for a customer names its own address, so the customer signs only
\`sender_auth\`.

It must be able to sign \`reserve_auth\`: on Solana a key account, not a program-owned
address such as a multisig vault; on EVM and Tron a key account or a contract that
supports ERC-1271. Any such address may be named except the gateway's own selector
(\`quote_selector\` in GET /v1/defaults), which signs no award and is refused with
\`400\` \`QUOTE_SELECTOR_NOT_ALLOWED\`.
`,
            example: '0x742D35cC6634c0532925a3b844Bc9e7595F41360'
        },
        fulfillment_verifier: {
            type: 'object',
            description: `The verification service that confirms the payment was delivered before the escrow
releases the source funds, and the account it signs with. Required on every chain:
the gateway's \`/v1/defaults\` response supplies it for each chain.
`,
            required: ['account', 'endpoint'],
            properties: {
                account: {
                    type: 'string',
                    description: 'The wallet address or public key of the verification service',
                    example: '0x892BB2e4F6b14a2B5b82Ba8d33E5925D42D4431F'
                },
                endpoint: {
                    type: 'string',
                    format: 'uri',
                    description: `Origin of the fulfillment verifier service, with no path — the caller
appends the verifier's own API paths. The gateway's \`/v1/defaults\` response
supplies the default fulfillment verifier for each chain.
`,
                    example: 'https://veri-fill.production-testnet.atum.xyz'
                }
            }
        },
        escrow_contract_address: {
            type: 'string',
            description: `Escrow contract on the source chain that holds the source funds until proof of
fulfillment has been verified. Required on every chain: the gateway's \`/v1/defaults\`
response supplies it for each chain (\`escrow_contract\`).
`,
            example: '0x742D35cC6634c0532925a3b844Bc9e7595F41360'
        },
        fulfillment_proxy: {
            type: 'string',
            description: 'Optional fulfillment-proxy contract address on the destination chain. Leave empty to use the default.',
            example: '0x892BB2e4F6b14a2B5b82Ba8d33E5925D42D4431F'
        },
        settler_requirements: {
            type: 'object',
            description: `Optional settler filtering. If whitelist is present, only whitelisted settlers may win.
If blacklist is present, blacklisted settlers are excluded. Both can be specified;
blacklist takes precedence (a settler in both is rejected).
`,
            properties: {
                whitelist: {
                    type: 'array',
                    description: 'Settler DIDs permitted to fulfill this request (W3C DID format). If present, only these may win.',
                    minItems: 1,
                    maxItems: 100,
                    uniqueItems: true,
                    items: {
                        type: 'string',
                        pattern: '^did:[a-z][a-z0-9]*:[a-zA-Z0-9._:%-]+$'
                    },
                    example: ['did:pkh:eip155:1:0x742D35cC6634c0532925a3b844Bc9e7595F41360']
                },
                blacklist: {
                    type: 'array',
                    description: 'Settler DIDs excluded from fulfilling this request (W3C DID format).',
                    minItems: 1,
                    maxItems: 100,
                    uniqueItems: true,
                    items: {
                        type: 'string',
                        pattern: '^did:[a-z][a-z0-9]*:[a-zA-Z0-9._:%-]+$'
                    },
                    example: ['did:pkh:eip155:1:0x892bb2E4F6b14a2B5b82bA8D33e5925d42d4432f']
                }
            }
        },
        '@context': {
            type: 'array',
            description: `Optional JSON-LD context URLs — present when the originator wraps the request in a W3C
Data Integrity envelope so a downstream verifier can recover the signer identity.
`,
            items: {
                type: 'string'
            }
        },
        proof: {
            '$ref': '#/components/schemas/DataIntegrityProof'
        },
        verifiableCredential: {
            type: 'array',
            description: 'Optional document-level W3C Verifiable Credentials (e.g. KnownToAtum about the request producer).',
            items: {
                '$ref': '#/components/schemas/VerifiableCredential'
            }
        }
    }
} as const;

export const $DataIntegrityProof = {
    type: 'object',
    description: 'W3C Data Integrity proof conforming to the Data Integrity 1.0 specification. Which of jws or proofValue is required depends on the cryptosuite named in type, and that pairing is checked where the proof is verified rather than by this schema, so a document can satisfy the schema and still be refused at verification.',
    required: ['type', 'created', 'verificationMethod', 'proofPurpose'],
    properties: {
        type: {
            type: 'string',
            description: 'Proof type identifier. ECDSA-secp256k1 (recoverable, EVM-compatible) for did:pkh:eip155:* signers; Ed25519 for did:pkh:solana:* and did:pkh:stellar:* signers.',
            example: 'EcdsaSecp256k1RecoverySignature2020'
        },
        created: {
            type: 'string',
            format: 'date-time',
            description: 'ISO 8601 timestamp when the proof was created. Canonicalize the value exactly as it appears in the raw JSON: parsing it into a date-time and re-serializing can change the spelling (Z versus +00:00), and a different spelling canonicalizes to different bytes, so the signature no longer verifies.',
            example: '2026-04-29T12:00:00Z'
        },
        verificationMethod: {
            type: 'string',
            description: "DID URL identifying the verification method, e.g., 'did:pkh:eip155:1:0x...#blockchainAccountId' for ECDSA or 'did:pkh:solana:<chain>:<addr>#SolanaMethod2021' for Ed25519 on Solana, or 'did:pkh:stellar:<network>:<G-account>#blockchainAccountId' for Ed25519 on Stellar.",
            example: 'did:pkh:eip155:42161:0xabc...#blockchainAccountId'
        },
        proofPurpose: {
            type: 'string',
            description: 'Purpose of the proof (e.g., assertionMethod, authentication).',
            example: 'assertionMethod'
        },
        jws: {
            type: 'string',
            description: 'Detached JWS signature in <base64url(header)>..<base64url(sig)> form, header {alg:ES256K-R, b64:false, crit:[b64]}. Required at runtime for EcdsaSecp256k1RecoverySignature2020.'
        },
        proofValue: {
            type: 'string',
            description: 'Multibase-encoded raw signature bytes. Required at runtime for Ed25519Signature2020; mutually exclusive with jws in practice.'
        }
    }
} as const;

export const $Quote = {
    type: 'object',
    description: 'One collected quote — the content-hash identifier plus the verbatim settler-signed FulfillmentQuote.',
    required: ['quote_id', 'fulfillment_quote'],
    properties: {
        quote_id: {
            type: 'string',
            description: `The canonical content hash of the settler-signed quote, the same value the escrow
commits on chain as the quote hash. Send it as \`quote_id\` to award this quote.
`,
            example: '0x4e7f...c2a1'
        },
        fulfillment_quote: {
            type: 'object',
            description: `The settler-signed FulfillmentQuote (structurally the canonical FulfillmentQuote/v1
declaration at https://schemas.atum.xyz/declarations/FulfillmentQuote/v1), returned
verbatim as an opaque signed document. A client recomputes quote_hash over the returned
bytes and verifies the settler signature before awarding the quote. quote_hash is
canonicalization-based (URDNA2015), so it is stable across JSON key-order/whitespace
normalization. The
returned bytes are hash-equivalent to, but not necessarily byte-identical with, what the
settler emitted (quotes are stored as JSONB, which normalizes on write). The gateway
still never re-serializes the quote through a typed struct (that renormalizes timestamp
values and WOULD change quote_hash), so the Go binding exposes it as a raw JSON passthrough.
`,
            'x-go-type': 'json.RawMessage'
        }
    }
} as const;

