export const $ReserveAuth = {
    type: 'object',
    description: `The reserve message naming the chosen quote's settler, signed by the quote request's
\`quote_selector\`. The escrow verifies it on chain against the \`reserver\` that
\`sender_auth\` names. It binds the deposit, the chosen quote's \`quote_id\`, the quote's
\`settler_address\` and its \`source_amount\`.

- EVM and Tron: the message is the escrow's reserve witness, \`{depositId, quoteHash,
  settler, sourceAmount}\`. The deposit id is derived from the signed \`sender_auth\`,
  \`keccak256(abi.encode(depositor, signature, nonce))\` over the Permit2 signature and
  nonce, so sign \`reserve_auth\` after \`sender_auth\`. \`message_prehash\` is the witness as
  typed data (EIP-712, TIP-712 on Tron), a JSON string \`{domain, types, primaryType,
  message}\` with \`primaryType\` \`ReserveWitness\`. The domain is \`name\` \`Escrow\`, \`version\`
  \`3\`, \`chainId\` as 0x-prefixed hex without leading zeros (its lower 32 bits on Tron) and
  \`verifyingContract\` the escrow, with no other member except an empty \`salt\`. Addresses
  are 0x-prefixed hex, on Tron too, and \`sourceAmount\` is a decimal string. \`message\` is
  the typed data's digest, and \`signature\` the \`quote_selector\`'s signature over it. A
  contract wallet signs as it does for ERC-1271.
- Solana: \`message\` is the escrow's reserve message hash, which binds the settler, the
  deposit hash that \`sender_auth\` signs, the quote hash and the source amount. None of
  these depends on the deposit signature, so the two can be signed in either order.
  \`message_prehash\` is the reserve record as a JSON string, \`{deposit_hash, recipient,
  quote_hash, source_amount}\`: the hashes as 0x-prefixed hex, \`recipient\` the settler's
  base58 address and \`source_amount\` a decimal string. \`signature\` is the
  \`quote_selector\`'s Ed25519 signature over \`message\`, so \`quote_selector\` must be a key
  that can sign.
- Stellar: \`message\` is the escrow's reserve digest, which binds the settler, the deposit
  id (the deposit digest that \`sender_auth\` signs), the quote hash and the source amount.
  None of these depends on the delegate's signature, so the two can be signed in either
  order. \`message_prehash\` is the reserve record as a JSON string, \`{deposit_id,
  quote_hash, settler, source_amount}\`: the hashes as 0x-prefixed hex, \`settler\` a \`G...\`
  or \`C...\` address and \`source_amount\` a decimal string. \`signature\` is the
  \`quote_selector\`'s Ed25519 signature over \`message\`, so \`quote_selector\` must be a
  \`G...\` account whose key can sign.`,
    required: ['message', 'message_prehash', 'signature'],
    properties: {
        message: {
            type: 'string',
            description: 'The 0x-prefixed 32-byte digest that `signature` signs, on every chain.',
            example: '0x5c0b4c7a3c5f5e1f8d3b0e2a9c7d6b5a4f3e2d1c0b9a8f7e6d5c4b3a2f1e0d9c'
        },
        message_prehash: {
            type: 'string',
            description: `The signed reserve, as a JSON string: the typed data on EVM and Tron, the reserve
record on Solana and Stellar, as described above.`
        },
        signature: {
            type: 'string',
            description: "The `quote_selector`'s signature over `message`, 0x-prefixed hex on every chain.",
            example: '0xabcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890ab1c'
        }
    }
} as const;

export const $ChainDefaults = {
    type: 'object',
    description: `The addresses for one chain. Optional fields appear only where they apply to that
chain; an absent optional field is not an error.
`,
    required: ['chain_id', 'quote_selector', 'escrow_contract', 'fulfillment_proxy', 'fulfillment_verifier'],
    properties: {
        chain_id: {
            type: 'string',
            description: 'CAIP-2 identifier of the chain these defaults describe, normalised to lower case.',
            example: 'eip155:84532'
        },
        quote_selector: {
            type: 'string',
            description: "The account named as the reserver in the deposit authorization of POST /v1/payments. Sign against this exact value there; a deposit reserved by anyone else is rejected. An award names its quote request's own `quote_selector` instead, and a quote request may not name this one.",
            example: '0xd0f080E23F95571D26eEb1FAD24a5F3d66835195'
        },
        escrow_contract: {
            type: 'string',
            description: 'The escrow the deposit is made into, and the spender of the token approval. Empty when the chain is not fully configured.',
            example: '0xa61a0C025943Aa79B73D8D07E3aDbEe1873738b4'
        },
        fulfillment_proxy: {
            type: 'string',
            description: "The contract that pays the receiver. Read this from the DESTINATION chain's defaults, not the source chain's. Empty when the chain is not fully configured.",
            example: '0x09A5a0d6955E5394A661Cd9E7007076fa63B4158'
        },
        fulfillment_verifier: {
            type: 'object',
            description: 'The service that attests settlement, and the account it signs with.',
            required: ['account', 'endpoint'],
            properties: {
                account: {
                    type: 'string',
                    description: 'The account named as the releaser in the deposit authorization. Sign against this exact value.',
                    example: '0x27050EE47befC43F4dF7807a7AA8073039e5fa89'
                },
                endpoint: {
                    type: 'string',
                    format: 'uri',
                    description: 'Base URL of the fulfillment verifier serving this chain.',
                    example: 'https://veri-fill.example.com'
                }
            }
        },
        permit2_contract: {
            type: 'string',
            minLength: 1,
            description: "The Permit2 this chain's escrow verifies against, sent only when it is not the canonical deployment. When absent, use the canonical Permit2 address for the chain. EVM and Tron only.",
            example: '0x000000000022D473030F116dDEE9F6B43aC78BA3'
        },
        tokens: {
            type: 'array',
            description: "Tokens this chain's escrow accepts for deposit. Absent when the gateway has no listing for the chain, which does not mean no token is accepted.",
            items: {
                type: 'object',
                required: ['symbol', 'address', 'decimals'],
                properties: {
                    symbol: {
                        type: 'string',
                        example: 'USDC'
                    },
                    address: {
                        type: 'string',
                        description: "Token contract address, in the chain's native address format.",
                        example: '0x036cbd53842c5426634e7929541ec2318f3dcf7e'
                    },
                    decimals: {
                        type: 'integer',
                        description: 'Decimal places, for converting a human amount to base units.',
                        example: 6
                    }
                }
            }
        },
        svm_signature_cluster_id: {
            type: 'string',
            description: "Solana only. The cluster the escrow's signing domain is bound to, needed to build the deposit hash. Absent for EVM and Tron.",
            example: 'devnet'
        },
        svm_signature_domain_version: {
            type: 'integer',
            minimum: 1,
            description: "Solana only. The escrow's signature domain version, which the deposit hash commits to. Absent for EVM and Tron.",
            example: 5
        },
        deposit_request_hash_version: {
            type: 'integer',
            minimum: 1,
            description: 'The depositRequestHash version to sign for a deposit from this chain: 1 is keccak256 of the request_id, 2 is the hash of the payment terms, computed over the request body exactly as it is then posted. Absent means 1. Kept for clients that predate `deposit_request_hash_versions`, which a client should read instead: a deposit signed with version 1 is still accepted unless that list omits 1. It stays 2 once version 1 is no longer accepted, so a client that reads only this member keeps signing version 2.',
            example: 2
        },
        deposit_request_hash_versions: {
            type: 'array',
            minItems: 1,
            uniqueItems: true,
            items: {
                type: 'integer',
                minimum: 1
            },
            description: 'The depositRequestHash versions a deposit from this chain may be signed with, ascending: `[1]` before version 2, `[1, 2]` once the gateway publishes 2 in `deposit_request_hash_version`, and `[2]` once it no longer accepts version 1. A merchant lists exactly these in an x402 or MPP challenge. Absent means `[1, 2]` when `deposit_request_hash_version` is 2 and `[1]` otherwise, which is what a gateway that predates this member implies. Ignore a version you do not know.',
            example: [1, 2]
        },
        direct_deposit_request_hash_version: {
            type: 'integer',
            minimum: 1,
            description: "The depositRequestHash version this gateway derives an originator-executed (direct) deposit's id at, and so the version that deposit's witness must commit: 1 is keccak256 of the request_id, 2 is the hash of the payment terms. Present on the chains a direct deposit can be made from (EVM). A deposit whose witness commits another version is still accepted by the escrow, under an id that names no payment, and comes back only through `refundUnreserved`. Absent from a gateway that predates this member: obtain the version from the gateway operator. Version 1 is deprecated for direct deposits. The gateway can change the version it derives at, so read this member for each direct deposit: a deposit funded at the old version and submitted after the change names no payment. A client that does not know the version must not make a direct deposit, since its deposit would name no payment: it upgrades instead. Unrelated to `deposit_request_hash_version` and `deposit_request_hash_versions`, which describe Permit2 signatures.",
            example: 2
        }
    }
} as const;

export const $GetDefaultsResult = {
    description: "Either one chain's defaults or every chain keyed by CAIP-2 chain id, depending on whether `chain_id` was supplied. A top-level `chain_id` identifies the first.",
    oneOf: [
        {
            '$ref': '#/components/schemas/ChainDefaults'
        },
        {
            '$ref': '#/components/schemas/ChainDefaultsByChain'
        }
    ]
} as const;

